// Lesefunktionen ohne Anmeldung. Alles andere (auch list_my_*, get_my_profile, Admin-Listen) braucht den persoenlichen Token.
const OPEN = new Set(["search_entities", "get_entity", "get_entity_questions", "get_help", "list_translation_tasks", "list_events", "get_event", "get_event_team", "search_members", "list_library", "list_guest_listings", "list_video_pitches", "list_podcast_pitches", "list_blog_posts", "list_questions", "get_wiki_term", "list_wiki_terms", "list_platform_updates", "list_feed_items", "list_wishes", "search_orgs", "list_org_offers", "list_event_sponsors"]);
export const needsToken = (t) => !OPEN.has(t.name);
// MCP-Annotations: Clients (Claude, ChatGPT, Copilot) fragen damit nur bei wirklich schreibenden Aktionen nach.
const WRITES = (t) => !!t.write && !/^get_my_/.test(t.name);
export const annotations = (t) => ({ title: t.name.replace(/_/g, " "), readOnlyHint: !WRITES(t), ...(WRITES(t) ? { destructiveHint: /^(delete_|mark_|set_event_role$|manage_event_partner$)/.test(t.name), idempotentHint: !/^(vote_|ask_|answer_|create_|register_)/.test(t.name) } : {}), openWorldHint: false });

